195: void __init arm64_memblock_init(void)
196: {
197: 	const s64 linear_region_size = -(s64)PAGE_OFFSET;
198: 
199: 	/*
200: 	 * Ensure that the linear region takes up exactly half of the kernel
201: 	 * virtual address space. This way, we can distinguish a linear address
202: 	 * from a kernel/module/vmalloc address by testing a single bit.
203: 	 */
204: 	BUILD_BUG_ON(linear_region_size != BIT(VA_BITS - 1));
205: 
206: 	/*
207: 	 * Select a suitable value for the base of physical memory.
208: 	 */
209: 	memstart_addr = round_down(memblock_start_of_DRAM(),
210: 				   ARM64_MEMSTART_ALIGN);
211: 
212: 	/*
213: 	 * Remove the memory that we will not be able to cover with the
214: 	 * linear mapping. Take care not to clip the kernel which may be
215: 	 * high in memory.
216: 	 */
217: 	memblock_remove(max_t(u64, memstart_addr + linear_region_size,
218: 			__pa_symbol(_end)), ULLONG_MAX);
219: 	if (memstart_addr + linear_region_size < memblock_end_of_DRAM()) {
220: 		/* ensure that memstart_addr remains sufficiently aligned */
221: 		memstart_addr = round_up(memblock_end_of_DRAM() - linear_region_size,
222: 					 ARM64_MEMSTART_ALIGN);
223: 		memblock_remove(0, memstart_addr);
224: 	}
225: 
226: 	/*
227: 	 * Apply the memory limit if it was set. Since the kernel may be loaded
228: 	 * high up in memory, add back the kernel region that must be accessible
229: 	 * via the linear mapping.
230: 	 */
231: 	if (memory_limit != (phys_addr_t)ULLONG_MAX) {
232: 		memblock_mem_limit_remove_map(memory_limit);
233: 		memblock_add(__pa_symbol(_text), (u64)(_end - _text));
234: 	}
235: 
236: 	if (IS_ENABLED(CONFIG_BLK_DEV_INITRD) && initrd_start) {
237: 		/*
238: 		 * Add back the memory we just removed if it results in the
239: 		 * initrd to become inaccessible via the linear mapping.
240: 		 * Otherwise, this is a no-op
241: 		 */
242: 		u64 base = initrd_start & PAGE_MASK;
243: 		u64 size = PAGE_ALIGN(initrd_end) - base;
244: 
245: 		/*
246: 		 * We can only add back the initrd memory if we don't end up
247: 		 * with more memory than we can address via the linear mapping.
248: 		 * It is up to the bootloader to position the kernel and the
249: 		 * initrd reasonably close to each other (i.e., within 32 GB of
250: 		 * each other) so that all granule/#levels combinations can
251: 		 * always access both.
252: 		 */
253: 		if (WARN(base < memblock_start_of_DRAM() ||
254: 			 base + size > memblock_start_of_DRAM() +
255: 				       linear_region_size,
256: 			"initrd not fully accessible via the linear mapping -- please check your bootloader ...\n")) {
257: 			initrd_start = 0;
258: 		} else {
259: 			memblock_remove(base, size); /* clear MEMBLOCK_ flags */
260: 			memblock_add(base, size);
261: 			memblock_reserve(base, size);
262: 		}
263: 	}
264: 
265: 	if (IS_ENABLED(CONFIG_RANDOMIZE_BASE)) {
266: 		extern u16 memstart_offset_seed;
267: 		u64 range = linear_region_size -
268: 			    (memblock_end_of_DRAM() - memblock_start_of_DRAM());
269: 
270: 		/*
271: 		 * If the size of the linear region exceeds, by a sufficient
272: 		 * margin, the size of the region that the available physical
273: 		 * memory spans, randomize the linear region as well.
274: 		 */
275: 		if (memstart_offset_seed > 0 && range >= ARM64_MEMSTART_ALIGN) {
276: 			range /= ARM64_MEMSTART_ALIGN;
277: 			memstart_addr -= ARM64_MEMSTART_ALIGN *
278: 					 ((range * memstart_offset_seed) >> 16);
279: 		}
280: 	}
281: 
282: 	/*
283: 	 * Register the kernel text, kernel data, initrd, and initial
284: 	 * pagetables with memblock.
285: 	 */
286: 	memblock_reserve(__pa_symbol(_text), _end - _text);
287: #ifdef CONFIG_BLK_DEV_INITRD
288: 	if (initrd_start) {
289: 		memblock_reserve(initrd_start, initrd_end - initrd_start);
290: 
291: 		/* the generic initrd code expects virtual addresses */
292: 		initrd_start = __phys_to_virt(initrd_start);
293: 		initrd_end = __phys_to_virt(initrd_end);
294: 	}
295: #endif
296: 
297: 	early_init_fdt_scan_reserved_mem();
298: 
299: 	/* 4GB maximum for 32-bit only capable devices */
300: 	if (IS_ENABLED(CONFIG_ZONE_DMA))
301: 		arm64_dma_phys_limit = max_zone_dma_phys();
302: 	else
303: 		arm64_dma_phys_limit = PHYS_MASK + 1;
304: 	high_memory = __va(memblock_end_of_DRAM() - 1) + 1;
305: 	dma_contiguous_reserve(arm64_dma_phys_limit);
306: 
307: 	memblock_allow_resize();
308: }
