729:  * @it: callback function
730:  * @data: context data pointer
731:  *
732:  * This function is used to scan the flattened device-tree, it is
733:  * used to extract the memory information at boot before we can
734:  * unflatten the tree
735:  */
736: int __init of_scan_flat_dt(int (*it)(unsigned long node,
737: 				     const char *uname, int depth,
738: 				     void *data),
739: 			   void *data)
740: {
741: 	const void *blob = initial_boot_params;
742: 	const char *pathp;
743: 	int offset, rc = 0, depth = -1;
744: 
745: 	if (!blob)
746: 		return 0;
747: 
748: 	for (offset = fdt_next_node(blob, -1, &depth);
749: 	     offset >= 0 && depth >= 0 && !rc;
750: 	     offset = fdt_next_node(blob, offset, &depth)) {
751: 
752: 		pathp = fdt_get_name(blob, offset, NULL);
753: 		if (*pathp == '/')
754: 			pathp = kbasename(pathp);
755: 		rc = it(offset, pathp, depth, data);
756: 	}
757: 	return rc;
